using System.Collections.Generic;

namespace osu.Game.Rulesets.Danmakusu.Bosses
{
    /// <summary>What a boss does, in a few sentences (shown in the boss menu), in two parts: what she shoots herself, and what else she does. The mechanics that are built have a text, the others are placeholders.</summary>
    public static class BossDescriptions
    {
        private const string stars = "Spirals of stars.";

        private static readonly Dictionary<BossMechanic, (string Basic, string Mechanics)> texts = new Dictionary<BossMechanic, (string Basic, string Mechanics)>
        {
            [BossMechanic.Blindness] = ("A ring of arrowheads every beat, flying straight.", "Every attack halves the speed of all bullets and turns a flashlight on: you can only see a small circle round you. The pauses restore everything."),
            [BossMechanic.Moon] = (stars, "A big moon and a triple laser circle the centre of the screen. Bullets vanish in the moon, but touching it hurts like a slider. All bullets are doubled in size and number, and her attack never pauses."),
            [BossMechanic.ButterflyFans] = ("Petals instead of stars.", "Her tree grows from the bottom of the screen; it grows 32 flowers of its own in every attack and every bullet that leaves the bottom grows one more (also while the tree grows: the flowers come out on the branches as soon as these have grown there), and in the end the petals fly off. Bullets that leave the top turn into petals and fall again."),
            [BossMechanic.Echo] = ("Paper talismans, in rings that turn the other way whenever new walls appear.", "Two glass walls close in during every attack (top and bottom, then left and right...). Every bullet bounces off them twice, then passes through."),
            [BossMechanic.Doors] = ("Talismans: backwards in an attack, forwards in the pauses.", "Portals open in the wall behind her and behind you; what comes out flies its own way, and a beam that has gone through keeps going in and coming out where the portals were when it first did."),
            [BossMechanic.Dowsing] = ("Arrowheads that fly straight.", "No pauses. Every sixteen beats the bullets round her turn into homing arrowheads and falling ellipses, twice as fast as they flew."),
            [BossMechanic.FantasySeal] = ("Paper talismans. Every few beats a ring of three yin-yang orbs that ricochet until the pause ends.", "During an attack every second bullet cannot leave the screen (the others fly out as ever): they stop at the border and pile up, spread evenly all round it and packed tight, body against body. When the pause ends, the pile is gone."),
            [BossMechanic.FateSpear] = ("Knives.", "Everything glows red, and a huge aimed spear of knives follows a short warning."),
            [BossMechanic.Freeze] = ("Arrowheads that fly straight.", "Her attack freezes every second bullet in the air at once, then lets them shatter outwards."),
            [BossMechanic.Gaps] = (stars, "Gaps open in the screen; bullets that go into one come out of another. A train comes at you when an attack begins and again in every pause. In every pause three bullets of every eight on the screen freeze and turn into talismans facing the middle of the screen; when the pause ends they fly at it, still talismans, through it and on out of the screen."),
            [BossMechanic.Lunatic] = ("Rings of twenty-five very short straight beams from a fixed spot.", "In every second attack every second bullet freezes in a dim purple light, then slides three circles to the left or the right (harmless while it slides); the others fly on. Every slice of a beam that is out of the playfield when its freeze comes is cut away at once."),
            [BossMechanic.MasterSpark] = ("Master Sparks: they start a circle wide and swell, ever more slowly, until they reach 5.4 circle radii from their middle to each side, then run straight, straight lines with thin edges, while she stands still (with another boss on the screen she keeps all of them). She stands where a boss stands, opposite you, but half as far from the middle of the screen. They come out fast, aimed at you, and keep that one way while they grow; once grown they choose which way round to turn (the way you are nearer right then) and turn towards you, five degrees a second, always that way round, and no mechanic of any boss touches them: nothing stops, turns, cuts, hides, thickens or recolours them.", "In her attacks every third bullet on the screen is a star that ricochets."),
            [BossMechanic.Nuclear] = ("Slow giant orbs that grow out of her with a heavy thud and burst into dense rings; they hurt like a slider body, and nothing can destroy them (the black hole, the other bosses' mechanics: they can only be frozen, pushed or sent through portals). Every ring of them is turned between the balls of the last.", "Her attacks and pauses last twice as long. Before each of her pauses everything on the screen slows to a stop and the black hole's music starts; in the pause a black hole in the middle, bending the light round it (every bullet near it is stretched into an arc, with a ring of light at its edge and bent stars round it), pulls everything but her big balls and Yuyuko's petals in at half speed (what the circles and sliders fire then comes in from outside the screen, straight at it), swallows what touches it (it shrinks away) and, all through the pause, shoots each of them out again split in two, one out of each of its two rays. Its cone of light shows where they go: it appears before the hole, aimed at you, and stands still; when the first bullet comes out the rays choose which way round to turn (towards you, right then) and turn that way very slowly, a quarter of a turn at most."),
            [BossMechanic.FreeFall] = ("Ellipses instead of stars.", "In an attack the bullets that leave the top stop there and fall freely, and every second one that comes inside her golden circle round you turns towards you, glowing gold. In the pauses new bullets ricochet one time more. She stands where the boss beside her does not: in the middle when that one stands opposite you, opposite you when it is in the middle; with two others always in the middle. Alone on the map, in every attack she does what another boss does instead, one of all the bosses with a mechanic of their own, with half its bullets."),
            [BossMechanic.Purification] = ("Slices of beam. Every slider of her section is a sliderwhistle, but its laser is fired from her, along the slider's path.", "Every slice of a beam is see-through and harmless for its first four beats. Every 8 beats she shoots every fourth bullet that appeared in them out again, as one ring at their average speed. What the other bosses do to beams only touches hers once a slice is fully formed."),
            [BossMechanic.Rebirth] = ("Nothing of her own but what her landings send out: twenty rings in a spiral.", "No pauses. She jumps at you in a straight line to the edge of the screen and stays there with a huge ball growing on her. Each landing shakes the screen. When the map's last boss section is over she comes back 8 beats later until the end, with everything twice as big; with Kaguya on the map both of them come back, each on her own half of everything."),
            [BossMechanic.ScreenMirror] = ("A ring of plain round bullets every beat, no big beams.", "In her attacks the whole playfield, cursor included, turns upside down. What is flying when the turn starts bounces once off the border and turns red. Four beats before every turn a see-through clone of her, with her magic circle and warning stars, shows where she will be seen after it, red arrows of her dress round you flash and point at her and a circle of them round her points in at her, and the whole screen fills with big see-through arrows, the ones on her dress: red ones flowing sideways and blue ones up or down, from the side you are nearer to towards the other, where the turn will throw you. After every turn a big red circle shows where you are (after the turn upside down it stays round you until the screen turns back), and while the screen is upside down a big see-through red glow lies round you."),
            [BossMechanic.Shikigami] = ("Fast bouncing bullets: arrowheads, every second one a basic bullet that flies straight.", "In every attack she is thrown across the screen."),
            [BossMechanic.Taiko] = (stars, "Five taiko drums circle her and are beaten in turn; each beat sends out a ripple that makes bullets swell; while a bullet is swollen it hurts like a slider body and is not used up."),
            [BossMechanic.Dango] = ("Round bullets.", "Every bullet leaves two copies behind it, and every three is skewered like dango: a thin beam runs through them, sticking out in front and behind, and hurts like a slider body, for as long as all three are there. Big bullets, fired with a heavy thud, turn the others round."),
            [BossMechanic.ThreeWorlds] = ("Three planets fire different patterns at once; hit orbs ricochet off the border and off each other.", "While thrown, the Earth and the Moon each swallow the bullets they touch (unseen) and shoot them all out of their edges at every impact as five rings, one right after the other, each spread evenly over 180 degrees away from the wall (what they shoot out they leave alone). Whenever they are not swallowing, the Earth and the Moon push bullets away, with a flash. A throw is never cut short: when the attack ends each flies on to its next impact first. Every 32 beats of an attack (not in one shorter than that) comes the World's Ender, with a warning, one at a time, the last going first; it takes the Earth and the Moon as they are, their chains breaking and every link flying off as a bullet, and goes through to its end also when her section is over. Over four beats, while the screen shakes, the Earth goes to the middle of the screen and grows as big as the playfield is high, under the bullets; once it has grown it hurts like a slider body, and so do all the chunks that come off it and the very big chunks of its halves, while they can be seen; the Moon goes very slowly round it, off its chain, its edge just touching the left and right walls, and the Sun shrinks. Four beats later the Sun crosses the Earth once from one side to the other, along the line that pointed at you at the start, leaving a jagged line of molten rock, and fades out, and orange cracks come up all over the Earth as it begins; the screen shakes until the split. Small, strongly glowing golden bullets, at speeds from half to one and a half times a plain bullet's, fly off to both sides all along the line as it passes, and away from the Earth at both ends, in chaotic bursts over 90 degrees, and chunks of the Earth break away there, leaving holes in it with molten edges, and fly off at one speed, molten at their broken edges. Two beats after the cut it splits. Right before that comes an impact frame of 200 ms: a white screen, everything black with a sharp white arc on the side towards the middle, long sharp stars with straight tails, each with its echoes, that jump about, never crossing, and turn what is under them inside out, sharp lines out from the split, and sharp streaks towards it that go on through the explosion, after which the bullets blur towards the split and the screen shakes hard, both dying away over eight beats. At the split the bullets come again, the other chunks break away at both ends with many more all along the cut, and the halves, cracking into very big chunks with molten edges, drift slowly off to the sides of the line, fanning out over 120 degrees."),
            [BossMechanic.TimeStop] = ("Knives.", "In an attack everything on the screen stands still while spirals of knives appear round her, and a faint green copy of everything, her knives too, and of what is fired meanwhile and flies on, shows where the mirroring will put it, if that is within four circle radii of you. When it ends, everything is mirrored and turns into knives, and the held knives fly out at you."),
            [BossMechanic.Unconscious] = ("Hearts, twice as big, twice as many in every ring as a boss's stars (in a spinner too).", "Bullets fire from random positions around you."),
            [BossMechanic.Unknown] = (stars, "Bullets whose shape and colour you can only make out when they are close. Her UFOs suck in every fourth bullet and shoot each one out four times."),
            [BossMechanic.Winter] = ("Arrowheads that fly straight.", "No pauses. Every slider is a sliderwhistle and shoots its beams; the beam is eaten away from its oldest end at half the speed it grew, each slice dissipating into small slow bullets as it goes that fly against the way the slider goes."),
            [BossMechanic.Darkness] = ("Rings of plain bullets that turn slowly.", "No pauses. Every eight beats she throws a ring of ten invisible circles; whatever is inside one - bullets and beams - cannot be seen, and is half see-through over the edge (the other bosses' own things, like Yukari's trains, stay as they are). The circles do nothing to you, and what they hide still hurts."),
            [BossMechanic.Bats] = ("Bats: everything she shoots is one.", "Every twentieth bullet on the screen turns into a bat. Bats fly as fast as Byakuren's beams and home in on you as they do, twice as fast as arrowheads turn: for eight beats they always turn back, even from past the edge of the screen, then they fly straight on; one that has stayed within two circle radii of you for four beats in all fades out. Bats dim the bullets around them."),
            [BossMechanic.SevenElements] = ("Squares of plain bullets.", "No pauses. Every eight beats the element changes. Fire: ripples turn bullets orange; their red rings flash before they swell, turn yellow and burn out. Water: of the bullets the thick blue ripples catch, every second one gets a see-through, harmless clone that rides the ripple outwards, on three rings side by side across it (each spread evenly over its visible part); four beats later the bullet is gone and its clone is solid, and four beats after that it leaves the ripple and flies on as the bullet did; the others slow to an eighth and slowly recover. Wood: every tenth bullet that leaves the playfield grows a glowing tree, whose ten leaves are thrown slowly at the centre. Metal: every bullet touched gets a frozen knife on top of it that aims at you, then flies. Earth: every twentieth bullet on the screen is a glowing brown stone as big as a circle that bursts into five bullets of its old size when it hits the wall."),
            [BossMechanic.Necromancy] = ("Talismans in ellipses.", "Every second bullet that leaves the playfield turns back: it flies the way it came at a quarter of its speed as a paper talisman, and fades out after sixteen beats."),
            [BossMechanic.Prism] = ("Triangles of plain bullets.", "A big prism turns in the middle. Bullets that cross it turn along its side, and leave mirrored and split into seven small rainbow bullets (every second bullet of a ring leaves whole, as it went in). The prism hurts."),
            [BossMechanic.Recollection] = ("Hearts, as Koishi's: twice as big, twice as many in every ring (in a spinner too).", "Every two beats she reads which way you moved (three eyes open round you before each reading, the first in front of you); bullets in the cone of 90 degrees of any of the eyes, within five circles, turn red and slowly turn to fly straight at the line you traced, perpendicular to it. You leave a red beam behind you: each slice of it is see-through and harmless for 4 beats, then hurts for 8 as it fades out - stand still and it catches up with you."),
            [BossMechanic.Qi] = ("Fans of plain bullets aimed at you.", "No pauses. In pulls of sixteen beats she draws in every bullet near her, even other bosses'; they are fed into one big growing ball (as big as all of them together, twice as fast as their average, as coloured as their average); every second bullet is left alone. When the pull ends the ball is thrown at you and the next pull begins at once; on its way the ball swallows every bullet it touches and grows. No ball's radius grows past 1.2 times the playfield's height. When its middle reaches a wall it sends out five rings of sixteen bullets from its middle, like Mokou's ball, and ricochets; at the next wall it impacts again and fades out."),
            [BossMechanic.Smoke] = (stars, "In her attacks she throws a ring of smoke clouds every eight beats. Bullets inside smoke are half transparent (not the other bosses' own things, like Yukari's trains), twice as big and hurt like a slider body. The smoke itself does not hurt."),
            [BossMechanic.Volley] = ("Arrowheads that fly straight.", "A quarter of the bullets per ring, but each is shot three times in a row, with more bullets beside each shot."),
            [BossMechanic.Death] = ("Plain bullets.", "No pauses. Every sixteen beats a grey ripple stops everything it passes; eight beats later it all falls as it is and darkens as it falls. A giant skull shows over a dimmed background."),
            [BossMechanic.Spring] = ("Rings of flowers that burst into petals. In a spinner they have half as many flowers, and come half as often as the spiral's shots.", "Branches grow from the four corners of the screen, always at the same speed (a short section only grows them part of the way). In her attacks bullets that leave the screen at a side grow flowers on the branches, evenly spread (half as often as Yuyuko's, as fast); eight beats after it appeared, each flower bursts into petals (small ones, as big as the petals of Yuyuko's tree, like the petals of her own flower bullets). In her pauses no new flowers grow, but the ones that are there still burst on time."),
            [BossMechanic.Momentum] = ("Rings of ellipses.", "No pauses. Every eight beats a push is announced: for four beats everything on the screen glows, turns light grey and shakes, and every eighth bullet swells to one and a half times its size. Then everything gets extra speed away from her, towards you, which adds up with every push. Every circle that is hit and every slider that is over gets a grey combo colour, glows a little and falls on you, darkening as it falls like Zanmu's bullets (a slider keeps its shape); after a moment they hurt like a slider body, circles too."),
            [BossMechanic.Inchling] = (stars, "In her attacks every bullet and beam, hitbox included, is half its size at the edge of her magic circle (and inside it) and grows gradually to one and a half times its size at the edge of the screen, glowing more the further it is. During the warning before an attack the sizes change to that and everything shakes; they change back after it. A wall sound plays at every attack."),
            [BossMechanic.Cloud] = ("Nothing of her own: the hands of her cloud do the hitting, and their walls and claps send out the rings.", "The cloud Unzan's head stands behind her (as seen from you) and faces you, with a hand on each side of her. In an attack every 8 beats one of its hands (left, right, left...) is first drawn slowly back, then thrown at you along an outer arc, speeding up; where it hits a wall far from her (never the two walls behind her) it sends out Mokou's rings, shakes the field for 4 beats and sounds like Hecatia's Moon, stays for two beats and comes back in a straight line. Hands that are home swing a little, slowly. During the warning the head grows and the hands fade in close to it and move out to their places; it all goes the other way when her phase is over. In a pause both hands slowly come together on the place where you were when they set off (and hurt there as they meet) and send out four rings of ellipses shaped like an arrowhead bullet (sharp tip, arc sides), with the same shake. She has only one warning, the one that brings Unzan in; the hands hurt while they are out, and a throw is never cut short: if her phase ends meanwhile, the hand still lands, stays and comes home before the cloud goes. A hand that is out swallows the bullets it touches (unseen) and shoots them all out at its next wall hit (or clap) as five rings, one right after the other, each spread evenly over 180 degrees away from the wall (at a clap: towards you)."),
            [BossMechanic.Silence] = ("Only rings of arc beams: every two beats a circle made of 10 arcs with wide gaps between them flies out from her, also in a spinner.", "In her attacks every hitsound is muted, the circles and sliders are hidden as with the Hidden mod, and bullets (their edges too) and beams get blurrier and glow more the further they are from her (what is inside her magic circle is normal; the hitboxes do not change). The outline of every slider then turns into a beam that grows outwards from it, all round it, until it has left the screen, in 20 pieces with gaps between them; it hurts like a slider body."),
            [BossMechanic.Scrolls] = ("When an attack begins, five beams as thin as a slider's start from round her, away from you, and home in on you like Sekibanki's heads. In a spinner five thin beams point outwards from her and spin.", "She remembers where every fifth circle and slider of her section starts (Doremy's and Sagume's copies too), up to 5 places at a time; 32 beats later a big star flashes up there for a beat (it hurts to touch) and five such beams start from round it, at least 2 beats after the place before. Her beams are as wide as a slider's and fast, with a star at the tip, and home in only for their first sixteen beats, then fly straight; like Koakuma's bats, a beam stops once it has been within two circle radii of you for eight beats in all, or has left the playfield after its homing is over; every part of it is there for 4 beats, narrowing away over the last two, so a beam ends in a point; while a star of hers is outside the screen a red arrow glows at the wall nearest to it, points at the wall, goes along with the star and grows as it comes nearer. Every fourth ricochet star fired in her sections has a beam for a tail, eight beats long. Her beams do not shake the screen."),
            [BossMechanic.Dream] = ("Plain bullets in two chains of three-bullet rings that turn opposite ways. No beams.", "No pauses. Every circle and slider has a dark blue copy mirrored through the middle of the playfield. A copy shoots what its original shoots, mirrored, with half as many bullets, three quarters as big and twice as fast, white and blue, glowing; so do the spinner's stars."),
            [BossMechanic.Heads] = (stars, "Every eight beats of an attack she throws one of her heads away from you; it turns back and chases you like Koakuma's bats for 64 beats, then fades. The head and the beam behind it (twice as wide as a slider's) hurt like a slider body: every part of it stays where the head was for 16 beats, then flies off the screen."),
            [BossMechanic.Rewind] = (stars, "No pauses: as soon as one of her attacks ends the next begins, and the one that ended is played again backwards over it: every circle and slider of it comes back white where it was, the last one first (sliders the other way along their path). They hurt like the originals and shoot what the originals shot the same way, white, with a quarter as many bullets, one and a half times as big and half as fast."),
            [BossMechanic.Return] = ("Paper talismans in rings shaped like a pentagon.", "With other bosses on the map she does what they do herself, with half their bullets and beams: in a section of her own the last one first and so on backwards, for sixteen beats each after a gap of four; in a section she shares what the boss beside her does, four beats later. Alone every second bullet that goes out of the screen in an attack is shot again from her instead, half as big and half as fast, towards the place where it left, and every slider's beam that reaches the edge is copied from her, half as wide."),
            [BossMechanic.Miracle] = ("Rings of thirty small ricochet stars in the shape of a star, each turned a little further, every second the other way.", "In her attacks every ring has twice as many bullets, half as big, and the round rings are five-pointed stars; the background turns a dim green with a giant faint star behind it."),
            [BossMechanic.Blades] = ("Rings of knives with long blades.", "In her attacks the bullets of every fifth circle or slider come out in a ring round where you are, fading in, and slowly fall away from it towards you. Four of every ten slider beams stop when their slider ends, turns to point at you while it straightens into a line, and four copies grow out of it to their places very far apart; then the row turns as one until its middle beam aims at you, flashes, and all five are thrown that way side by side, parallel."),
            [BossMechanic.Traps] = (stars, "Every sixteen beats she puts three bear traps down where you are, two beats apart, each with an approach circle. When it has closed the trap is set with a thud. Step into one and it snaps shut: it hurts and holds you where you are for two beats, with a red glow round you. One nobody steps into snaps shut by itself 32 beats after it was put down. At most 6 traps on the map; the oldest fades out."),
            [BossMechanic.Haste] = ("Basic bullets in double rings.", "No pauses. Every ring is shot twice, right after each other; every bullet on the screen, whoever fired it, speeds up, more and more, to two and a half times its speed by the end of each of her long attacks; every fourth bullet is a little bigger and every fourth beam twice as thick. Meanwhile the background dims grey, the bullets blur towards the middle of the screen, speed lines come in from the edges, and a riser climbs to its highest right as the attack ends."),
            [BossMechanic.ImpossibleRequests] = ("Every two beats a ring of twenty bullets followed by three more, half a beat apart, each turned a little further than the one before, so that they spin; in a spinner too.", "She stands at the top of the screen and never pauses, under a giant moon that comes slowly down in a dark blue sky. Every fourth bullet that leaves the top falls back as a star, three degrees to the left or to the right of straight down, leaving a beam behind it that narrows to a point, whose slices live for four beats. Slider beams that leave the top fall back in short purple pieces. Every ring fired in her sections turns the other way from the one before. Eight beats after the last boss section she comes back until the song ends (with Mokou on the map both of them do): slices live for eight beats, every second bullet falls, bullets change between ellipses, stars, talismans and all three mixed every four beats, and every twentieth is three times as big."),
            [BossMechanic.Rays] = ("Every four beats sixteen big glowing bullets fly at her from outside the screen, the first from behind you.", "She stands in the middle and never pauses. Every eight beats the thirty 3 degree cones from the middle of the screen to its edge that hold the most bullets light up, and the bullets in them glow and are pulled to her. A cone comes up faint and grows clearer over its first six beats; the cones brighten for two beats and after eight turn into bright beams for four, hurting like a slider body, while the screen dims; as they fade, what was pulled in comes out of her as five even rings. When her section ends she stays where she stood until her last beams and rings are over."),
            [BossMechanic.Slash] = ("Rings of straight beams that fly out of her, all the time, in a spinner too.", "In her attacks she watches every sixteenth bullet; every two beats eighteen thin slashes go through them, two by two, spread as widely over the screen as the bullets allow, leaving out what is at its edge, across the whole screen, see-through and harmless for four beats, then solid and twice as thick for two, hurting like a slider body, before it fades. As a slash turns solid it cuts the bullets across it in two along it: one part flies on the way it was going, the other the opposite way. Where it crosses a slider's beam it pokes a hole in it, and the slices fall like petals."),
            [BossMechanic.Verdant] = (stars, "In her attacks the background dims dark warm green and every bullet turns green, a quarter bigger, and glows. What is fired meanwhile hurts like a slider body and goes round once: when it leaves the screen it comes in again on the same line from the opposite wall, and is gone the second time it leaves. Those bullets cannot be destroyed: what would take one away only gets a copy of it, and the bullet flies on. A bullet that has left the screen has lost her buff: it comes in again its own size and colour, without the glow, is used up by a hit and can be destroyed."),
            [BossMechanic.Tide] = ("Hollow bubbles, a quarter as many as a boss's stars, all through her section (in a spinner the spinner's stars too): they hurt as bullets do, and each pops into a ring of eight bullets sixteen beats later.", "In her attacks the screen dims ocean blue and bullets and beams turn blue, and what is fired swims from side to side by a circle radius (not the rings Junko shoots out again), and hurts like a slider body instead of being used up by a hit. In her section the sliders fire no beams. Every sixteenth bullet is a hollow bubble twice as big: it hurts as a bullet does, and sixteen beats after it appeared it pops into a ring of eight bullets half as big as it was, flashing red for the last four. Every eighth bullet that goes out of the bottom grows a blade of dark green seaweed there over two beats, each its own height between an eighth and three eighths of the screen, with a sharp tip, that sways, hurts like a slider body, and after eight beats comes off the ground and falls upwards. Six green petals grow on every blade, and they hurt while they are on it too; as it comes off the ground they spread away from it as petal bullets that flutter as they fly. Every bullet that swims leaves a trace of beam behind it, following its way for two beats, as wide all along, that hurts like a slider body."),
            [BossMechanic.Storm] = ("Lightning at you, every four beats of an attack, which stays the way it was aimed; see-through and harmless at first, as every bolt is.", "The screen dims dark grey and heavy thunderclouds hang along the top, over the lightning and the rain, flashing where a bolt starts. Every bullet that goes out of the top falls back where it left as a bright ellipse half its size, never dim. Every two beats a jagged bolt of lightning, glowing, all of one piece with its branches, grows from the top to the bottom, with thin, fainter branches and smaller branches that narrow to a tip, light blue at first, white and half again as thick once it is solid; it is see-through (faintly) and harmless for eight beats, then solid for four, hurting like a slider body, and bullets near it are dim; every second bolt thunders, heard only while it is solid. As a bolt turns solid, five small bullets of its colour fly back from where it ends, spread over 120 degrees, never dim. In a spinner the clouds are in the middle, and ellipses and bolts go from there outwards."),
            [BossMechanic.Possibility] = ("Nothing but flowers of beams: every two beats a five-petalled flower grows out of where she stands, every petal two smooth arcs that meet at a sharp tip, with gaps between the petals, and hurts like a slider body.", "In her attacks every tenth bullet on the screen has a beam for a tail, four beats long, that flies along with it. A big bright red flash warns of her pauses: in them everything, bullets and beams, is pulled straight away from her, hard, a big grey wave goes out from her, and the screen shakes."),
            [BossMechanic.Stacking] = ("Rings of ellipses.", "Every four beats every bullet on the screen gets as much speed again at right angles to the line between it and her: clockwise within one circle radius of her, anticlockwise within two, clockwise within three, and so on. In her attacks bullets whose bodies touch stick together, body against body, up to eight in a clump, and fly on as one, half again as fast as the law of impulse says (never slower than half again the fastest of them)."),
            [BossMechanic.Foxes] = ("Rings of eight talismans that start twice as fast as usual and slow down to a quarter of their speed a playfield's length out.", "When an attack begins, and every eight beats of it, eight beams grow fast out of where she stands along golden spirals, each such fan on its own; where they start stays where it is. Once all eight have passed the edge of the screen they go from the end they started at, as fast as they grew. All that time, while they grow too, a bullet that crosses one bounces off it, twice at most. While they grow, their tips cut the bullets on their way in two along the spiral: one part flies on the way it was going, the other the opposite way. The beams hurt like a slider body."),
            [BossMechanic.Drift] = (stars, "Everything fired in her section loses speed the nearer it gets to the wall ahead of it, down to 0.3 of its speed at the wall. When a pause starts a big ship comes at you, bow first, twenty circles long, out of the wall nearest her from behind her: all of it hurts like a slider body, and no bullet stays in it: every bullet that gets into it slides out to its nearest edge, fast but smoothly, and is turned once to fly straight out of the ship."),
            [BossMechanic.Misfortune] = ("Talismans in hexagons; one that goes out of the screen comes back in the way it came, once.", "Every eight beats everything on the screen, bullets and beams, turns dark blue and flies back the way it came; what she has turned does not turn again. For the four beats before that, small red arrows of Seija's dress, not see-through, flash beside the bullets that will really turn, each pointing the way its bullet will go."),
            [BossMechanic.Market] = ("Every four beats, every two in a spinner, a ring of talismans five circle radii round you closes in slowly on where you are.", "Every eight beats two walls of big talismans come in slowly, at half a plain bullet's speed, side by side with no gap between them, from the top and the bottom, the next time from the left and the right. A talisman of a wall that comes within four circle radii of you turns into a small knife with a blue handle, stops its flight and creeps at where you were at a quarter of a plain bullet's speed, so the walls part round you and the knives pile up."),
            [BossMechanic.Judgement] = ("Very dense rings of talismans.", "When an attack begins a magic circle, 4.8 circle radii from its middle to its edge, is placed round you and stays where it is, and another as big where it is mirrored through the middle of the screen. You can be in either of them but cannot leave them, by any way of moving: you stay on the border of the nearer one at most (with the cursor you jump across to the other when it is nearer). They do not hurt. Whatever enters one of them, bullets and beams, turns to its middle at half its speed, flies on through, and has its speed back when the circles are gone. Bullets outside the circles are dim. The circles fade out in the pause."),
            [BossMechanic.Claws] = ("Rings of bright white bullets, twice as fast as any, as she flies at you, and as fast as any while she stays.", "No pauses. When her section begins, and every sixteen beats, she howls and throws herself as fast as Chen at where you were at that moment, and stays there for eight beats. All that time, every beat, she claws at you: three thin arcs side by side round her, as far from her as you are, so they reach anywhere, turned 45 degrees round you clockwise and the next one as far the other way, so they cross like her swings. A claw, narrow, grows faint and harmless from one tip to the other in half a beat and stays so; two beats after it began it lights up in a quarter of a beat (every second one with a swing), hurts like a slider body for a beat and fades out. When it lights up it cuts whatever is in it at that moment in two along the arc, bullets (never more unevenly than 8 to 2) and beams (never more unevenly than 20 to 1; not Marisa's), but not the objects of the bosses: one part flies on the way it was going, the other the opposite way."),
            [BossMechanic.Reaping] = ("Bats like Koakuma's that do not home, a lot of them, all round her: twice as many as a boss's stars, flying until they leave the screen.", "No pauses. She slides fast after you until you are within reach of her scythe, half the playfield's height long, and on the next mark of two beats stops for a blow. The warning: a thin arc round her at the scythe's reach, faint and harmless, grows from tip to tip as fast as it will light up, and stays so until two beats after it began. The blow: her scythe appears and swings round very quickly the way the arc grew, lighting it up from tip to tip, and she stays where she is until the swing is over. What has lit up hurts like a slider body, four beats from the start of the swing; the scythe itself is harmless, and close to her you are under it. When it lights up it cuts whatever is in it in two along the arc, bullets (never more unevenly than 8 to 2) and beams (never more unevenly than 20 to 1; not Marisa's), but not the objects of the bosses: one part flies on the way it was going, the other the opposite way."),
            [BossMechanic.HalfMoon] = ("Stars with tails of beams, four beats long, that narrow to a point.", "No pauses. Every sixteen beats a giant crescent moon appears on you, its back to the outside of the screen: white with a thin grey outline and a soft glow, see-through and harmless at first, it grows from one tip to the other over four beats while the screen shakes. Then it lights up the same way round and is solid for eight beats: it hurts like a slider body, and everything that flies into it, bullets and beams alike (not Yukari's train), bounces off it once, with a flash where it does. Before it goes its glow flashes; then it fades out while stars with short tails fly off all along both its edges. A moon always goes through to its end, also after her section: she stays until it is over. The next moon grows the other way round."),
            [BossMechanic.Earthquake] = ("Ricochet stars.", "Every sixteenth bullet that goes out of the bottom of the screen is shot back up as three bullets half its size, fanned out over 120 degrees. Every eight beats she sends out a shockwave and the screen shakes for as long as it is on it; meanwhile every eighth bullet that goes out of a wall the wave has reached comes back in the same way."),
            [BossMechanic.Recording] = ("Four rings of plain bullets at once, each slower than the last.", "Every four beats of an attack everything within five and a half circle radii of you is recorded, and a bright circle, clear in the middle, fades in there: the bullets fly on, and each leaves a see-through preview where it was, in the colour of her hair (black with a violet sheen), wherever you go. Two beats later the previews turn solid and fly off, as big as the bullets were and the way they were going. Every slider's beam fired in her attacks is fired again four beats later from the same place."),
            [BossMechanic.Bloodlust] = ("Bats like Koakuma's that do not home, half as fast, and fly until they leave the screen.", "In her attacks three rings of uneven pools of blood with vampire's fangs in them turn round her, three, five and seven circle radii away, each ring the other way round. A bullet that touches a pool turns red and glowing, as at the end of Remilia's attack, and is aimed at you as you are at that moment; it does not turn again. The pools themselves do not hurt."),
            [BossMechanic.Shockwave] = ("Rings of plain bullets twice as big as usual.", "Every eight beats she stamps: the screen shakes and a smooth ring goes out from where she stands. A bullet it touches is thrown outwards, 2.5 times as fast right by her, less and less further out, down to 1.2 times at the distance of the wall, and it glows the more the faster it was thrown."),
            [BossMechanic.Fortune] = ("Golden bullets, a quarter as often as a boss's stars, each pulled gently the way she threw it, that bounce off every wall like a ball, twice, keeping 70 % of their energy, and then leave the screen.", "Every two beats every tenth bullet on the screen turns gold, glows and is pulled the way it was going (each bullet has its own gravity, which stays as it was), bouncing off any wall of the screen like a ball, twice, keeping 70 % of its energy every time, and then its gravity takes it out of the screen. In an attack the share grows from every tenth bullet to every fourth by its end, and starts over with the next attack."),
            [BossMechanic.Flowers] = (stars, "Every fourth bullet that goes out of the bottom of the screen grows into a sunflower there: the heads are alike, the stems all different, so the bottom of the screen looks like a field, swaying left and right. Only the dark brown head hurts, like a slider body. It flashes on the ground a beat before it comes out. After eight beats the stem shrinks back and the head flies up, five degrees to the left or to the right by turns, while its petals leave it as a slow ring of sixteen yellow petals."),
            [BossMechanic.Autumn] = ("Autumn leaves: orange maple leaves.", "In her attacks every second bullet on the screen turns orange, more and more. When a pause starts each of them is a leaf that stops and falls slowly, swaying, to the bottom of the screen, and there two leaves fade in for each, evenly spread. They turn slowly as they fall. After her next attack starts they fall upwards just as slowly, not all at once, five degrees to the left or to the right, half of them each way, each turning at a speed of its own."),
            [BossMechanic.Stampede] = ("Nothing but rings of beams, all the time, in a spinner too; they hurt like a slider body, and have gaps to slip through.", "Her attacks are like Remilia's: the rings on the screen get denser and turn further as an attack goes on, every fortieth bullet is three times as big and everything glows more and more, without the red. The background dims brown and a giant see-through horse's head shows through it. When an attack begins the line from her to you is taken, as with Zanmu's fall, and every bullet on the screen, also what is fired during the attack, turns that way. Every bullet speeds up to 1.2 times its speed over an attack and slows down to its own again over the pause. Every four beats of an attack every fourth bullet on the screen shoots two bullets half its size, one to its left and one to its right."),
            [BossMechanic.Swarm] = (stars, "All through her section every fourth bullet on the screen, whoever fired it, is a firefly: twice as big, bright green, with bloom and a pulsing glow of the same green. It leaves its way, drifting on slowly and wandering restlessly from side to side, but not far."),
            [BossMechanic.Crescent] = ("Rings of arrowheads that fly straight.", "In her attacks every bullet on the screen, whoever fired it, goes round as fast as it flies, at any distance, half of them one way and half the other, round where she stood when it was fired (what was on the screen already, round where she stood when the attack began): the middle of each stays where it is when she moves on. When the attack ends they fly on straight the way it left them. Every fourth ring fired in an attack is three times as dense."),
            [BossMechanic.Destruction] = ("Knives, from her and from three clones that turn round her.", "No pauses. Every eight beats she puts three red eyes down where you are, two beats apart; four beats later each explodes, taking every bullet and every piece of beam within about 3.4 circles of it (and you, if you are there). Each clone shoots what was blown up again, one after the other, twice as fast and half as big, outwards from the eye; the new bullets glow and cannot be blown up. Every fourth one also sends four bullets out along the axes."),
            [BossMechanic.Anchors] = ("Nothing but her anchors: big silver anchors on chains of bubbles, one thrown at you every eight beats, in a spinner too.", "She stands in the middle and never pauses. Every sixteen beats she throws eight anchors round her, one every half beat, evenly round the circle. Each flies slowly to the wall in four beats, chained to her by a string of bubbles, and stops with its crown a little out of the wall with a heavy metal clang, which shakes the screen for a moment; it stays there for eight beats, and then it is unchained and slowly crawls on out of the playfield the way it flew, fading, and its bubbles pop one after another from her out to the anchor over two beats, each into a ring of six small bullets that spread away. Anchors and bubbles hurt like a slider body."),
            [BossMechanic.Orbs] = ("A yin-yang orb at you every eight beats, in a spinner too: one and a half times as big as Reimu's, it ricochets off the edges of the screen and off the other orbs, hurts like a slider body and is gone after sixteen beats.", "Every thirtieth bullet turns into one of her orbs where it is and flies on its way; at most twelve fly at once (the oldest shrinks away). In her attacks bullets whose bodies touch ricochet off each other, once each."),
            [BossMechanic.Fissure] = ("Every four beats she stomps: everything within four circle radii of her is thrown on twice as fast, glowing like magma, with a narrow tail of beam two beats long, and bursts into four small ellipses at the wall. The stomp hurts you if you are in it, and thick cracks of magma in the ground round her hurt like a slider body for two beats. Every sound of hers plays twice at once.", "Every sixteen beats a wide crack of glowing magma, two circles across and as jagged as the World's Ender's cut, splits the ground from her towards you and out past the edge of the screen. It hurts like a slider body, and eight beats later it explodes into glowing magma ellipses off both its sides."),
            [BossMechanic.Scorch] = ("Every four beats five rings of five ricochet stars, from five places round her.", "In her attacks five beams come out of her, as thick as a spinner's and widening as they go, the first aimed at you, turning slowly together towards you. Every slice of a beam goes out as far from her as you were when it was fired, and leaves a scorch mark burning there for eight beats that hurts like a slider body (charred, with a glowing edge round all the burnt ground). When her attack ends, what is still flying goes on out to the edge of the screen."),
            [BossMechanic.Recall] = ("A fan of five knives with yellow handles at you every two beats.", "Every eighth bullet turns into a yellow-handled knife that stops and falls towards where you were, faster and faster. Everything that goes out of the screen is remembered sixteen beats at a time, and comes back in the next four beats as knives, in the order it left and four times as close together, each from where it left and straight across from that wall; in the beat before, every wall flashes gold."),
            [BossMechanic.Pagoda] = ("Every four beats a ring of sixteen beams that wave from side to side as they fly out, gently near her and faster and faster further out.", "She stands in the middle of the screen. A thick, glowing cross of beams grows out of her past every edge, a big star on its middle, and turns, clockwise in her attacks and anticlockwise in her pauses, half as fast as before, flashing another colour in the beat before it turns the other way; it hurts like a slider body. Every fourth bullet fired comes out of the cross instead, spread evenly along its arms, flying straight across it to one side or the other."),
            [BossMechanic.Constellation] = (stars, "Every eight beats every four bullets on the screen that are nearest each other are joined by a thin silver beam into a constellation, which hurts like a slider body; only the bullets of the constellations stand still, for four beats, then fly on. Constellations never overlap, nor cross themselves. For the four beats before, the beams show see-through where the bullets will stop."),
            [BossMechanic.Icosahedron] = ("An arc of beam ten degrees wide at you every quarter beat, flying out from her.", "In every attack a giant icosahedron of beams (one for every edge) fades in round the middle of the playfield, turning about the line through two of its corners across the screen and spinning round its middle too, every next attack the other way round; it grows to as wide as the playfield over eight beats and stays the whole attack. When the attack is over it comes apart into plain bullets half the size, flying out from its middle."),
            [BossMechanic.FallenAngel] = ("Every four beats two beams three circles wide come down from the top, one over where you are and one somewhere else: a see-through preview for four beats, then they hurt for four.", "She stands in the middle; her big white wings come out of her, open and sway, and they hurt like a slider. Every second bullet fired comes out of her wings instead, as a glowing feather, and flies away from her."),
            [BossMechanic.Jiangshi] = ("A fan of five knives with red handles at you every two beats.", "As Seiga: every fourth bullet that leaves the playfield turns back as a paper talisman - at its own speed, for two beats, and leaving copies of itself behind it all the way, end to end, each staying where it is left for eight beats."),
            [BossMechanic.Familiar] = ("Rings of sixteen talismans every two beats; every two neighbouring talismans of a ring are joined by a beam, see-through and harmless for four beats, then hurting.", "Socrates, her cat, twice as big as a bullet, comes out of her with a cry; every two beats it jumps onto a bullet within four circle radii of it and rides it - one whose leap goes over you if it can, else the one nearest you - and it jumps more often the further it is from you. It hurts like a slider body, leaping too."),
            [BossMechanic.PipeFox] = ("A ring of six big balls, two circles across each, at you every four beats (her spinner too), each ring turned half a step from the last.", "Every fourth beam of her section bounces once off the edge of the screen. Every tenth bullet fired in her section comes out of her big balls instead, the six in turn, and flies on the way it was fired."),
            [BossMechanic.Haniwa] = ("A very dense square of plain bullets every four beats; in her spinner round bullets in squares.", "In her section the rings come half as often with twice as many bullets, and every ring is a square. Every fifth bullet that goes out of the screen comes back the way it came as a beam four beats long, until it has crossed the screen. Every ring of the map is a square in her section, also those another boss changes."),
            [BossMechanic.Koto] = ("Beams four times as thick as a normal one fall slowly from the top of the screen in 18 lanes, where an 18-key osu!mania convert of the map has its notes: an approach circle closes at the top of the lane first, then the beam falls and reaches the bottom on its note; held notes are long beams.", "No pauses: the whole section is the convert, from her first beat to her last, over the map's own circles and sliders."),
            [BossMechanic.Strings] = ("Three parallel beams at you in her attacks, turning after you as they fire; in her spinner round bullets.", "Every slider's beam in her section has another one above it and below it, see-through and harmless for four beats. Every second bullet that crosses a beam becomes a note: it flies at half its speed, swelling to twice its speed and back every two beats, and turns towards you once."),
            [BossMechanic.Snowflake] = ("One giant snowflake of beams after another, standing still where she was (you are between two of its arms when it begins): six arms thick with side branches, twigs and twigs of twigs, all one seamless piece, every beam ending in a sharp tip.", "No pauses. A snowflake grows from its middle out over eight beats, as Yuyuko's tree grows, then goes again from the middle out over the next eight, coming apart into plain bullets half the size that fly out from its middle; then the next one begins."),
            [BossMechanic.Galaxy] = ("Every half beat five endless straight beams round her, bent 20 degrees like the arms of a galaxy, their starts joined by beams into a five-pointed star, see-through and harmless for four beats, then solid for four, then fading out; the sets go slowly through every colour of the rainbow; each set stays where she was when it came, and is turned five degrees from the last, the same way round for 32 beats and then the other way.", "No pauses. Every eight beats every bullet on the screen turns into a star like Marisa's and ricochets once off the edge of the screen."),
            [BossMechanic.Metamorphosis] = ("Rings of sixteen blue butterflies every four beats, the first at you, in a spinner too: they flap their wings and drift out slowly, wandering from side to side as Wriggle's fireflies do.", "Every eight beats every twentieth bullet on the screen (her butterflies too) turns aquamarine and flies at half its speed with a red ring round it, as Patchouli's fire, flashing faster and faster at the end. Four beats later it swells with Mokou's impact sound to a big round bullet two circle radii wide, glowing, at its own speed again, and over the last beat of the next four it shrinks back."),
            [BossMechanic.Poltergeist] = ("A fan of three bullets twice as big as usual at you every eight beats.", "Every sixteen beats 32 bullets stop where they are; over four beats they grow to twice their size, turn white and glow, and a red arrow beside each shows the way it will go (blinking over the last beat). Eight beats after they stopped they fly off, each its own way, twice as fast, and ricochet off the edges of the screen three times."),
        };

        public const string PLACEHOLDER = "None yet: this boss is still a placeholder.";

        /// <summary>What the line of a boss's difficulty starts with: the number follows (<see cref="Mods.BossInfoPanel"/> shows it as stars).</summary>
        public const string DIFFICULTY = "Difficulty: ";

        /// <summary>A boss's difficulty and the two parts of her text, one line each.</summary>
        public static string Of(BossInfo boss)
        {
            var (basic, mechanics) = boss.IsModified && texts.TryGetValue(boss.Mechanic, out var text) ? text : (stars, PLACEHOLDER);
            return $"{DIFFICULTY}{BossDifficulty.Of(boss)}\nBasic Attack: {basic}\nMechanics: {mechanics}";
        }

        /// <summary>The things that mechanics change and that two mechanics can fight over: for each, what each mechanic does with it (the mechanics that are not in a list do nothing there).</summary>
        private static readonly (string Title, string Both, Dictionary<BossMechanic, string> Does)[] domains =
        {
            ("the edge of the screen", "Both change what happens to bullets at the edge of the screen", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.FantasySeal] = "bullets stop there and pile up",
                [BossMechanic.Echo] = "glass walls bounce them",
                [BossMechanic.FreeFall] = "the top stops them and drops them",
                [BossMechanic.ButterflyFans] = "the top turns them into falling petals",
                [BossMechanic.Death] = "a ripple drops them",
                [BossMechanic.Return] = "they are shot again from her",
                [BossMechanic.Destruction] = "an explosion near you takes them and shoots them again",
                [BossMechanic.ScreenMirror] = "they bounce off it once",
                [BossMechanic.Shikigami] = "they bounce off it",
                [BossMechanic.ThreeWorlds] = "orbs ricochet off it",
                [BossMechanic.Necromancy] = "they come back at a quarter of the speed",
                [BossMechanic.Jiangshi] = "they come back leaving a trail of talismans",
                [BossMechanic.SevenElements] = "every tenth one grows a tree there in her wood phase",
                [BossMechanic.Spring] = "every one that leaves grows a flower on a branch there",
            }),
            ("time", "Both stop or freeze what is flying", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Freeze] = "everything freezes at the start of her attack",
                [BossMechanic.TimeStop] = "time stands still in her attacks",
                [BossMechanic.Lunatic] = "everything freezes in her attacks",
                [BossMechanic.Death] = "her ripple stops what it passes",
            }),
            ("what you can see", "Both take away your view", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Blindness] = "a flashlight is all you see",
                [BossMechanic.Smoke] = "smoke clouds make bullets see-through",
                [BossMechanic.Darkness] = "invisible circles hide the bullets in them",
                [BossMechanic.Unknown] = "shapes and colours hide until the bullets are close",
            }),
            ("the sliders", "Both rewrite every slider", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Purification] = "the lasers come from her",
                [BossMechanic.Winter] = "every slider shoots beams that dissipate into bullets",
            }),
            ("the speed of the bullets", "Both change how fast the bullets fly", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Blindness] = "all bullets are half as fast in an attack",
                [BossMechanic.Volley] = "each bullet is shot three times in a row",
                [BossMechanic.HalfMoon] = "her moon bounces them off",
            }),
        };

        /// <summary>The text of a boss or of two bosses together: every boss with what he does, one after the other.</summary>
        public static string Combined(IReadOnlyList<BossInfo> bosses)
        {
            var parts = new List<string>();

            foreach (var boss in bosses)
                parts.Add($"{boss.Name}\n{Of(boss)}");

            return string.Join("\n\n", parts);
        }

        /// <summary>Where the mechanics of two bosses fight over the same thing, one sentence for each such thing; null if they do not (or there is only one boss).</summary>
        public static string? Clash(IReadOnlyList<BossInfo> bosses)
        {
            if (bosses.Count < 2)
                return null;

            var a = bosses[0];
            var b = bosses[1];
            var lines = new List<string>();

            foreach (var (_, both, does) in domains)
            {
                if (a.IsModified && b.IsModified && does.TryGetValue(a.Mechanic, out string? first) && does.TryGetValue(b.Mechanic, out string? second))
                    lines.Add($"{both}: {a.Name} - {first}; {b.Name} - {second}.");
            }

            if (a.IsModified && b.IsModified && a.Mechanic == b.Mechanic)
                lines.Add($"The same mechanic twice: {a.Name} and {b.Name} do the same thing at once.");

            return lines.Count == 0 ? null : string.Join("\n", lines);
        }
    }
}
